import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict with side, price, qty, arrival, active
    arrival_counter = 0

    def add_to_book(order_id, side, price, qty, arrival):
        book[order_id] = {'side': side, 'price': price, 'qty': qty, 'arrival': arrival, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, order_id))
        else:
            heapq.heappush(sell_heap, (price, arrival, order_id))

    def pop_best_buy():
        while buy_heap:
            negprice, arrival, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return oid, info
        return None, None

    def pop_best_sell():
        while sell_heap:
            price, arrival, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return oid, info
        return None, None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        arrival = arrival_counter
        arrival_counter += 1

        if side == 'buy':
            while remaining > 0:
                sid, sinfo = pop_best_sell()
                if sid is None:
                    break
                if typ != 'market' and sinfo['price'] > price:
                    break
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sinfo['price'], trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)
            if remaining > 0 and typ == 'limit':
                add_to_book(oid, side, price, remaining, arrival)

        else:  # sell
            while remaining > 0:
                bid, binfo = pop_best_buy()
                if bid is None:
                    break
                if typ != 'market' and binfo['price'] < price:
                    break
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, binfo['price'], trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)
            if remaining > 0 and typ == 'limit':
                add_to_book(oid, side, price, remaining, arrival)

    return trades

